syntax = "proto3";

package KNIRVCHAIN;

option go_package = "KNIRVCHAIN/internal/protocol/proto";

import "google/protobuf/timestamp.proto";

message TransactionProto {
  string from = 1;
  string to = 2;
  uint64 value = 3;
  bytes data = 4;
  google.protobuf.Timestamp timestamp = 5;
  uint64 fee = 6;
  string type = 7;
  bytes signature = 8;
  bytes public_key = 9;
}

message BlockProto {
  uint64 block_number = 1;
  bytes prev_hash = 2;
  google.protobuf.Timestamp timestamp = 3;
  int32 nonce = 4;
  repeated TransactionProto transactions = 5;
  string proposer_address = 6;
}

// LLMRootingData contains the core metadata for an LLM model rooting transaction
message LLMRootingDataProto {
  string model_name = 1;
  string model_owner = 2;
  string api_endpoint = 3;
  string metadata_cid = 4;
  string cmu = 5;
}---
syntax = "proto3";

package KNIRVCHAIN;

option go_package = "./;proto"; // Adjust go_package

import "google/protobuf/struct.proto";
import "google/protobuf/timestamp.proto";

// Enum for InteractionType
enum InteractionTypeProto {
  INTERACTION_TYPE_PROTO_UNSPECIFIED = 0;
  INTERACTION_TYPE_PROTO_TOOL_INVOCATION = 1;
  INTERACTION_TYPE_PROTO_PROMPT_USAGE = 2;
  INTERACTION_TYPE_PROTO_RESOURCE_ACCESS = 3;
  INTERACTION_TYPE_PROTO_PLUGIN_EXECUTION = 4;
  INTERACTION_TYPE_PROTO_SAMPLING_REQUEST_SENT = 5;
  INTERACTION_TYPE_PROTO_SAMPLING_RESPONSE_RECEIVED = 6;
  INTERACTION_TYPE_PROTO_MEMORY_WRITE = 7;
  INTERACTION_TYPE_PROTO_CAPABILITY_REGISTRATION = 8;
}

// ContextRecordProto corresponds to ContextRecord
message ContextRecordProto {
  string id = 1;
  string capability_id = 2;
  InteractionTypeProto interaction_type = 3;
  string initiator = 4;
  google.protobuf.Timestamp timestamp = 5;
  string input_hash = 6;
  string output_hash = 7;
  google.protobuf.Struct details = 8; // Maps to map[string]interface{}
  bytes signature = 9; // Keep as bytes for signature
}

// For transaction data
message MCPInvokeCapabilityDataProto {
  ContextRecordProto context_record = 1;
}---
syntax = "proto3";

package KNIRVCHAIN;

option go_package = "KNIRVCHAIN/internal/protocol/proto";

import "google/protobuf/struct.proto";
import "google/protobuf/timestamp.proto";

// Enum for CapabilityType
enum CapabilityTypeProto {
  CAPABILITY_TYPE_PROTO_UNSPECIFIED = 0;
  CAPABILITY_TYPE_PROTO_RESOURCE = 1;
  CAPABILITY_TYPE_PROTO_TOOL = 2;
  CAPABILITY_TYPE_PROTO_PROMPT = 3;
  CAPABILITY_TYPE_PROTO_MEMORY_SERVICE = 4;
}

// Enum for DiscoveryResourceType (used within ResourceDescriptor)
enum DiscoveryResourceTypeProto {
  DISCOVERY_RESOURCE_TYPE_PROTO_UNSPECIFIED = 0;
  DISCOVERY_RESOURCE_TYPE_PROTO_FILE = 1;
  DISCOVERY_RESOURCE_TYPE_PROTO_API = 2;
  DISCOVERY_RESOURCE_TYPE_PROTO_PLUGIN = 3;
  DISCOVERY_RESOURCE_TYPE_PROTO_GENERATED_DOCUMENT = 4;
  DISCOVERY_RESOURCE_TYPE_PROTO_DATASET = 5;
  DISCOVERY_RESOURCE_TYPE_PROTO_MODEL_ARTIFACT = 6;
  DISCOVERY_RESOURCE_TYPE_PROTO_SERVICE = 7;
}

// BaseDescriptorProto corresponds to BaseDescriptor
message BaseDescriptorProto {
  string id = 1;
  CapabilityTypeProto capability_type = 2;
  string name = 3;
  string owner = 4;
  string version = 5;
  string description = 6;
  uint64 gas_fee_nrn = 7;
  google.protobuf.Timestamp timestamp = 8;
  google.protobuf.Struct custom_metadata = 9;
}

// PluginSchemaDetailProto corresponds to PluginSchemaDetail
message PluginSchemaDetailProto {
  string summary = 1;
  google.protobuf.Struct access_info = 2;
  repeated string location_hints = 3;
  string manifest_file = 4;
  string executable_file = 5;
  string output_directory_hint = 6;
}

// ResourceDescriptorProto corresponds to ResourceDescriptor
message ResourceDescriptorProto {
  BaseDescriptorProto base_descriptor = 1;
  DiscoveryResourceTypeProto resource_type = 2;
  string content_hash = 3;
  PluginSchemaDetailProto schema = 4;
}

// ToolDescriptorProto corresponds to ToolDescriptor
message ToolDescriptorProto {
  BaseDescriptorProto base_descriptor = 1;
  string input_schema_json = 2;
  string output_schema_json = 3;
  string execution_pointer = 4;
}

// PromptDescriptorProto corresponds to PromptDescriptor
message PromptDescriptorProto {
  BaseDescriptorProto base_descriptor = 1;
  string template = 2;
  string parameters_schema_json = 3;
}

// MemoryServiceDescriptorProto corresponds to MemoryServiceDescriptor
message MemoryServiceDescriptorProto {
  BaseDescriptorProto base_descriptor = 1;
  string graph_schema = 2;
}

// Main CapabilityDescriptorProto using oneof
message CapabilityDescriptorContainerProto {
  oneof descriptor {
    ResourceDescriptorProto resource = 1;
    ToolDescriptorProto tool = 2;
    PromptDescriptorProto prompt = 3;
    MemoryServiceDescriptorProto memory_service = 4;
  }
}

// For transaction data
message MCPRegisterCapabilityDataProto {
  string capability_id = 1;
  string capability_type = 2;
  CapabilityDescriptorContainerProto capability_descriptor = 3;
  string owner_address = 4;
  uint64 fee = 5;
}

// For transaction data update
message MCPUpdateCapabilityDataProto {
  CapabilityDescriptorContainerProto capability_descriptor = 1;
}---
