  MEMORY_PERMISSION_DENIED = 3;
}

message MemoryPolicy {
  uint32 short_term_window_size = 1;
  uint32 episodic_top_k = 2;
  uint32 semantic_top_k = 3;
  uint32 procedural_top_k = 4;
  float relevance_threshold = 5;
